    typealias SwiftType = CredentialShape

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CredentialShape {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .key
        
        case 3: return .url
        
        case 4: return .unsupported(reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CredentialShape, into buf: inout [UInt8]) {
        switch value {
        
        
        case .none:
            writeInt(&buf, Int32(1))
        
        
        case .key:
            writeInt(&buf, Int32(2))
        
        
        case .url:
            writeInt(&buf, Int32(3))
        
        
        case let .unsupported(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


